multi_queries.type_and_summary:
PREFIX hist: <http://www.example.org/korean-history#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "이순신" || ?entityLabel = "참전" || ?entityLabel = "이순신탄신제" || ?entityLabel = "이순신 탄핵·파면 사건" || ?entityLabel = "선조의 교서(이순신에게 내린 교서, 간행 1795)" || ?entityLabel = "황석산성 전투" || ?entityLabel = "해정창전투" || ?entityLabel = "상주전투" || ?entityLabel = "본국송환" || ?entityLabel = "한산 진영")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

